import * as T from './vendor/three.module.min.js';
import {TikiKit} from './tiki-geometry-v76.js';
import {vendingDrinkTextures,initializeVendingTextures,vendingTextures} from './vending-materials-v70.js';
const cache=new Map(),ROOT=new URL('./textures/tiki-garden-v85/drinks/',import.meta.url);
const files=['falernum-fizz-basecolor','falernum-fizz-normal','falernum-fizz-roughness','mai-tai-breeze-basecolor','mai-tai-breeze-normal','mai-tai-breeze-roughness','coconut_peel-basecolor','coconut_peel-normal','coconut_peel-roughness','coconut_top-basecolor','coconut_top-normal','coconut_top-roughness','coast-lightbox-basecolor','orange_wheel-basecolor','cherry_strawberry-basecolor','mint_leaf-basecolor','parasol_pink_top-basecolor','parasol_lime_top-basecolor','citrus_pulp-basecolor'];
export async function preloadGardenDrinks85(report=()=>{}){if(!vendingTextures()['waterfall-ad'])await initializeVendingTextures();const loader=new T.TextureLoader();let i=0,done=0;await Promise.all(Array.from({length:3},async()=>{while(i<files.length){const key=files[i++];if(!cache.has(key)){const t=await loader.loadAsync(new URL(key+'.webp',ROOT).href);t.colorSpace=/normal|roughness/.test(key)?T.NoColorSpace:T.SRGBColorSpace;t.anisotropy=4;cache.set(key,t);}report(++done/files.length);}}));for(const c of ['basecolor','normal','roughness']){const t=await loader.loadAsync(new URL('./textures/tiki-v76/counter-wood/'+c+'.png',import.meta.url).href);t.colorSpace=c==='basecolor'?T.SRGBColorSpace:T.NoColorSpace;t.wrapS=t.wrapT=T.RepeatWrapping;t.anisotropy=4;cache.set('table-'+c,t);}}
export const gardenDrinkTexture85=k=>cache.get(k);
export const gardenDrinkTextures85=()=>[...cache.values()];
export const vendingDrinkName=type=>({pet:'Before the Storm · Falernum Fizz',can:'Mai Tai Breeze · Almond & Orange Blossom Soda',soy:'Small Shaved Green Coconut'})[type]||'Tropical almond water';
function profile(type,height,radius,mass,segments){return{type,height,radius,mass,friction:.45,restitution:.10,rollingFriction:.009,centerOfMass:[0,height*.46,0],compoundSegments:segments,segments};}
export const VENDING_DRINK_PROFILES={pet:profile('pet',.255,.034,.46,[{y0:0,y1:.025,r0:.029,r1:.034},{y0:.025,y1:.17,r0:.034,r1:.034},{y0:.17,y1:.20,r0:.034,r1:.014},{y0:.20,y1:.255,r0:.014,r1:.014}]),can:profile('can',.121,.045,.33,[{y0:0,y1:.012,r0:.039,r1:.045},{y0:.012,y1:.107,r0:.045,r1:.045},{y0:.107,y1:.121,r0:.045,r1:.038}]),soy:profile('soy',.113,.054,.22,[{y0:0,y1:.027,r0:.031,r1:.052},{y0:.027,y1:.075,r0:.052,r1:.054},{y0:.075,y1:.113,r0:.054,r1:.030}])};
export function createVendingDrink(_T,type='pet'){const tx=gardenDrinkTexture85,old=vendingDrinkTextures(),pbr=(stem,extra={})=>new T.MeshPhysicalMaterial({map:tx(stem+'-basecolor'),normalMap:tx(stem+'-normal'),roughnessMap:tx(stem+'-roughness'),normalScale:new T.Vector2(.38,.38),roughness:.67,metalness:0,...extra});
 const m={green:pbr('falernum-fizz',{color:0x47965d,roughness:.15,clearcoat:.75,clearcoatRoughness:.06,ior:1.51}),label:pbr('falernum-fizz',{roughness:.60,normalScale:new T.Vector2(.12,.12)}),ceramic:pbr('mai-tai-breeze',{roughness:.86,clearcoat:.10}),peel:pbr('coconut_peel',{roughness:.88}),top:pbr('coconut_top',{roughness:.9}),metal:new T.MeshStandardMaterial({color:0xc2c2b1,metalness:.94,roughness:.29,map:old.metal,normalMap:old.canTopNormal,normalScale:new T.Vector2(.22,.22)}),canTop:new T.MeshStandardMaterial({map:old.canTop,normalMap:old.canTopNormal,roughness:.31,metalness:.92}),dark:new T.MeshStandardMaterial({color:0x15191a,roughness:.72}),seal:new T.MeshStandardMaterial({color:0xc8b765,metalness:.74,roughness:.37})};
 let glassGrain=cache.get('bottle-glass-grain');if(!glassGrain){glassGrain=tx('falernum-fizz-basecolor').clone();glassGrain.offset.set(.02,.88);glassGrain.repeat.set(.065,.085);glassGrain.needsUpdate=true;cache.set('bottle-glass-grain',glassGrain);}m.green.map=glassGrain;
 const k=new TikiKit(m);function lathe(key,rows,n=24,uvScale=1){const g=new T.LatheGeometry(rows.map(p=>new T.Vector2(...p)),n),a=g.attributes.uv,pos=g.attributes.position,min=Math.min(...rows.map(p=>p[1])),max=Math.max(...rows.map(p=>p[1]));for(let i=0;i<a.count;i++)a.setY(i,(pos.getY(i)-min)/(max-min));k.add(g,key);}function cap(key,y,r){const g=new T.CircleGeometry(r,28);g.rotateX(-Math.PI/2);k.add(g,key,0,y,0);}function ring(key,y,r,t){k.add(new T.TorusGeometry(r,t,5,28),key,0,y,0,[Math.PI/2,0,0]);}
 if(type==='pet'){
  lathe('green',[[0,0],[.027,0],[.034,.006],[.034,.165],[.031,.178],[.014,.202],[.014,.246],[.016,.248],[.016,.253],[.010,.253]],28);
  lathe('label',[[.0346,.039],[.0346,.141]],28);ring('green',.023,.0342,.0018);ring('green',.155,.0342,.0017);ring('green',.182,.027,.0018);
  // Thick bottle embossing is real relief along the shoulder and heel.
  for(let j=0;j<16;j++){const a=j/16*Math.PI*2;k.beam('green',[Math.sin(a)*.034,.009,Math.cos(a)*.034],[Math.sin(a)*.034,.031,Math.cos(a)*.034],.0011,4);}
  k.cyl('seal',0,.251,0,.017,.017,.008,28);for(let j=0;j<20;j++){const a=j/20*6.283;k.beam('seal',[Math.sin(a)*.017,.247,Math.cos(a)*.017],[Math.sin(a)*.017,.255,Math.cos(a)*.017],.0008,3);}cap('seal',.2552,.016);
 }else if(type==='can'){
  lathe('ceramic',[[.037,0],[.043,.004],[.045,.012],[.045,.106],[.039,.116],[.037,.117]],28);cap('canTop',.118,.0375);ring('metal',.119,.0376,.0018);ring('metal',.003,.039,.0015);
  const opening=new T.CircleGeometry(.008,16);opening.rotateX(-Math.PI/2);k.add(opening,'dark',0,.1185,-.012,null,[.75,1,1.25]);const tab=new T.TorusGeometry(.008,.002,4,16);tab.rotateX(Math.PI/2);k.add(tab,'metal',0,.121,.003,null,[.72,1,1.45]);k.cyl('metal',0,.1205,.014,.002,.002,.002,8);
 }else{
  lathe('peel',[[0,0],[.031,.004],[.052,.028],[.054,.063],[.049,.079],[.027,.105]],10);lathe('top',[[.049,.078],[.039,.101],[.027,.113],[0,.113]],10);cap('top',.1134,.027);k.cyl('dark',.009,.1138,.005,.006,.006,.001,12);ring('peel',.015,.041,.0012);
 }
 const group=k.finish('Tropical vending / '+vendingDrinkName(type));group.userData={gardenVending:true,vendingDrink:true,almondHeight:VENDING_DRINK_PROFILES[type].height,type,ownedMaterials:Object.values(m)};group.traverse(o=>{if(o.isMesh){o.castShadow=false;o.receiveShadow=true;}});return{group,profile:VENDING_DRINK_PROFILES[type]};}
export function releaseVendingDrink(group){if(!group)return;group.traverse(o=>o.geometry?.dispose());group.userData.ownedMaterials?.forEach(m=>m.dispose());group.userData.ownedTextures?.forEach(t=>t.dispose());group.removeFromParent();}
